"""
generate_sensitivity_summary.py

This module creates a final markdown report summarising the stability of the
Pearson correlation coefficient (r) across the hyper‑parameter sweep
(sensitivity analysis) and the ablation study.

It reads two JSON artefacts produced by earlier pipeline steps:

* ``artifacts/reports/sensitivity_report.json`` – generated by the
  sensitivity sweep (task T043).  Expected format::

      {
          "sweep": [
              {
                  "config": {"msg_passes": 1, "lr": 0.001, ...},
                  "pearson_r": 0.78,
                  "rmse": 0.12
              },
              ...
          ]
      }

* ``artifacts/reports/ablation_report.json`` – generated by the ablation
  study (task T025b).  Expected format (at minimum) includes the raw
  correlation values for the full‑model and the ablated model for both the
  GNN and the baseline, e.g.::

      {
          "gnn_full_r": 0.81,
          "gnn_ablated_r": 0.73,
          "baseline_full_r": 0.69,
          "baseline_ablated_r": 0.62,
          "gnn_variation_delta": 0.08,
          "baseline_variation_delta": 0.07
      }

The script aggregates **all** Pearson‑r values found in the two artefacts,
determines whether every value meets the stability threshold of ``0.7``,
and writes a markdown file ``artifacts/reports/sensitivity_summary.md``
with a clear ``stability`` field (``stable`` or ``unstable``).

The implementation purposefully raises an error if the required JSON
files are missing – this guarantees that the pipeline will not silently
fabricate a summary when upstream steps have failed.
"""

import json
from pathlib import Path
from typing import List, Dict, Any

from utils.config import get_project_root

# ---------------------------------------------------------------------------
# Helper functions
# ---------------------------------------------------------------------------

def _load_json(path: Path) -> Dict[str, Any]:
    """Load a JSON file and return its content.

    Parameters
    ----------
    path: Path
        Path to the JSON file.

    Returns
    -------
    dict
        Parsed JSON content.

    Raises
    ------
    FileNotFoundError
        If ``path`` does not exist.
    json.JSONDecodeError
        If the file cannot be parsed as JSON.
    """
    if not path.is_file():
        raise FileNotFoundError(f"Required report not found: {path}")
    with path.open("r", encoding="utf-8") as fh:
        return json.load(fh)


def _extract_pearson_r_from_sensitivity(sensitivity_data: Dict[str, Any]) -> List[float]:
    """
    Extract all ``pearson_r`` values from the sensitivity sweep report.

    The expected structure is ``{\"sweep\": [{...\"pearson_r\": <float>, ...}, ...]}``.

    If the structure deviates, a ``KeyError`` will be raised – this is
    intentional so that malformed upstream output is surfaced early.
    """
    sweep = sensitivity_data["sweep"]
    return [entry["pearson_r"] for entry in sweep]


def _extract_pearson_r_from_ablation(ablation_data: Dict[str, Any]) -> List[float]:
    """
    Extract every Pearson‑r value present in the ablation report.

    The function looks for keys that end with ``"_r"`` (e.g. ``gnn_full_r``)
    and returns their numeric values.
    """
    r_values = []
    for key, value in ablation_data.items():
        if key.endswith("_r"):
            # Ensure the value is a float/int; otherwise let the exception surface.
            r_values.append(float(value))
    return r_values


def _determine_stability(r_values: List[float], threshold: float = 0.7) -> str:
    """
    Determine stability based on a threshold.

    Returns ``"stable"`` if **all** values are greater than or equal to the
    threshold, otherwise ``"unstable"``.
    """
    return "stable" if all(r >= threshold for r in r_values) else "unstable"


def _format_sensitivity_table(r_values: List[float]) -> str:
    """
    Produce a simple markdown table listing the Pearson‑r values from the
    sensitivity sweep.
    """
    lines = ["| Index | Pearson r |", "|---|---|"]
    for idx, r in enumerate(r_values, start=1):
        lines.append(f"| {idx} | {r:.4f} |")
    return "\n".join(lines)


def _format_ablation_table(ablation_data: Dict[str, Any]) -> str:
    """
    Produce a markdown table that shows the raw correlation values from the
    ablation study.
    """
    # Extract only the keys that end with ``_r`` and sort them for deterministic output.
    r_items = sorted(
        ((k, float(v)) for k, v in ablation_data.items() if k.endswith("_r")),
        key=lambda kv: kv[0],
    )
    lines = ["| Metric | Pearson r |", "|---|---|"]
    for metric, r in r_items:
        lines.append(f"| {metric} | {r:.4f} |")
    return "\n".join(lines)


# ---------------------------------------------------------------------------
# Core functionality
# ---------------------------------------------------------------------------

def generate_summary() -> Path:
    """
    Generate ``sensitivity_summary.md`` based on the two upstream reports.

    Returns
    -------
    Path
        The path to the generated markdown file.
    """
    project_root = get_project_root()

    # Define expected input artefacts
    sensitivity_json_path = project_root / "artifacts" / "reports" / "sensitivity_report.json"
    ablation_json_path = project_root / "artifacts" / "reports" / "ablation_report.json"

    # Load the JSON files (will raise if they are missing or malformed)
    sensitivity_data = _load_json(sensitivity_json_path)
    ablation_data = _load_json(ablation_json_path)

    # Gather all Pearson‑r values
    r_values = []
    r_values.extend(_extract_pearson_r_from_sensitivity(sensitivity_data))
    r_values.extend(_extract_pearson_r_from_ablation(ablation_data))

    # Determine overall stability
    stability = _determine_stability(r_values, threshold=0.7)

    # Build the markdown content
    md_lines = [
        "# Sensitivity & Ablation Summary",
        "",
        "## Sensitivity Sweep (Hyper‑parameter Grid)",
        "",
        _format_sensitivity_table(_extract_pearson_r_from_sensitivity(sensitivity_data)),
        "",
        "## Ablation Study (Solvent Descriptor Removal)",
        "",
        _format_ablation_table(ablation_data),
        "",
        f"**Stability:** `{stability}`",
        "",
        "*All Pearson‑r values were evaluated against the stability threshold of 0.7.*",
    ]

    markdown_content = "\n".join(md_lines)

    # Write the markdown file
    output_path = project_root / "artifacts" / "reports" / "sensitivity_summary.md"
    output_path.parent.mkdir(parents=True, exist_ok=True)
    with output_path.open("w", encoding="utf-8") as fh:
        fh.write(markdown_content)

    return output_path


# ---------------------------------------------------------------------------
# CLI entry point
# ---------------------------------------------------------------------------

def main() -> None:
    """
    CLI entry point used by ``python code/training/generate_sensitivity_summary.py``.
    """
    try:
        summary_path = generate_summary()
        print(f"Sensitivity summary written to: {summary_path}")
    except Exception as exc:
        # Re‑raise after printing a helpful message – the pipeline runner expects
        # a non‑zero exit code on failure.
        print(f"Failed to generate sensitivity summary: {exc}")
        raise


if __name__ == "__main__":
    main()